insert into public.plans (key, name, description) values ('free', 'Free', 'Game 1 and your statue, free forever.') on conflict (key) do nothing;
insert into public.entitlements (plan_id, feature_key, limit_value) values ((select id from public.plans where key = 'free'), 'statue_rerolls', 1) on conflict (plan_id, feature_key) do nothing;
insert into public.plans (key, name, description) values ('pro', 'Pro', 'Extra statue re-rolls and Pro perks.') on conflict (key) do nothing;
insert into public.entitlements (plan_id, feature_key, limit_value) values ((select id from public.plans where key = 'pro'), 'statue_rerolls', 5) on conflict (plan_id, feature_key) do nothing;
insert into public.games (slug, title, type, status, config) values ('g1', 'Self-Development', 'free', 'active', '{"id":"g1","title":"Self-Development","worlds":{"inner":{"name":"The Inner World","description":"internal self-control, thoughts and health."},"outer":{"name":"The Outer World","description":"external lifestyle, environment and daily choices."}},"pillars":[{"id":"mental","world":"inner","name":"Mental","covers":"focus, learning new skills, controlling thoughts, a growth mindset."},{"id":"physical","world":"inner","name":"Physical","covers":"nutrition, exercise, consistent sleep, daily energy."},{"id":"emotional","world":"inner","name":"Emotional","covers":"emotional intelligence, processing feelings, responding rather than reacting."},{"id":"spiritual","world":"inner","name":"Spiritual","covers":"core values, sense of purpose, deeper meaning."},{"id":"financial","world":"outer","name":"Financial","covers":"managing, saving and investing money; career growth and stability."},{"id":"social","world":"outer","name":"Social","covers":"relationship quality, communication, boundaries."},{"id":"environmental","world":"outer","name":"Environmental","covers":"organized home and workspace, minimal digital clutter."},{"id":"recreational","world":"outer","name":"Recreational","covers":"hobbies, play, relaxation, breaks from work."}],"ramp":[{"id":"initiate","fromWeek":1},{"id":"apprentice","fromWeek":2},{"id":"adept","fromWeek":3},{"id":"full_protocol","fromWeek":4}],"bonusXp":{"fullSet":25,"innerBalance":50,"outerBalance":50,"balancedWeek":100,"perfectWeek":250},"books":{"questId":"g1.read","pagesField":"pages","bookIdField":"bookId","finishedXp":150},"eventDecorations":{"perfect_week":"gold_vein","book_finished":"laurel_leaf","balanced_week":"plinth_carving"},"feedsSculpture":true}'::jsonb) on conflict (slug) do nothing;
insert into public.quests (game_id, key, pillar, title, description, why, founding, schedule, "window", proof, xp, unlock, sort_order) values ((select id from public.games where slug = 'g1'), 'g1.read', 'mental', 'Read 10 pages a day from a self-development book', 'Ten pages of a self-development book, every day. Log the page count against a book on your shelf and keep a one-line takeaway.', 'Ten pages a day compounds into a dozen books a year — small daily cuts, not heroic binges. Every finished book is a boss kill: +150 XP and a laurel leaf carved on your statue.', true, '{"kind":"daily"}'::jsonb, '{"kind":"anytime"}'::jsonb, '{"type":"reading","targetPages":10}'::jsonb, 20, '{"kind":"ramp_stage","atLeast":"initiate"}'::jsonb, 1) on conflict (game_id, key) do nothing;
insert into public.quests (game_id, key, pillar, title, description, why, founding, schedule, "window", proof, xp, unlock, sort_order) values ((select id from public.games where slug = 'g1'), 'g1.exercise', 'physical', 'Exercise 4 days a week (20+ minutes)', 'Any 20+ minutes of real movement — lift, run, swim, sport, a hard walk — four days a week. Log what you did and for how long.', 'The body is the statue''s scaffolding: energy, mood and focus all ride on it. Four weeks on-target carves the Iron Will honor.', true, '{"kind":"weekly_quota","perWeek":4}'::jsonb, '{"kind":"anytime"}'::jsonb, '{"type":"duration","minMinutes":20}'::jsonb, 30, '{"kind":"ramp_stage","atLeast":"initiate"}'::jsonb, 2) on conflict (game_id, key) do nothing;
insert into public.quests (game_id, key, pillar, title, description, why, founding, schedule, "window", proof, xp, unlock, sort_order) values ((select id from public.games where slug = 'g1'), 'g1.journal', 'emotional', 'Journal once a day', 'Write at least 50 words about the day — or scan a handwritten page straight from your notebook. Entries are encrypted at rest; only you can read them.', 'Putting the day into words turns noise into signal — you respond to your life instead of reacting to it. A 30-day streak carves Unbroken.', true, '{"kind":"daily"}'::jsonb, '{"kind":"anytime"}'::jsonb, '{"type":"journal","minWords":50}'::jsonb, 15, '{"kind":"ramp_stage","atLeast":"initiate"}'::jsonb, 3) on conflict (game_id, key) do nothing;
insert into public.quests (game_id, key, pillar, title, description, why, founding, schedule, "window", proof, xp, unlock, sort_order) values ((select id from public.games where slug = 'g1'), 'g1.stillness', 'spiritual', '5 minutes of stillness', 'Five minutes of stillness — meditation, prayer, gratitude — or one line on what matters most today.', 'The pause between feeling and response is a muscle. Five quiet minutes a day trains the part of you that chooses.', false, '{"kind":"weekly_quota","perWeek":5}'::jsonb, '{"kind":"anytime"}'::jsonb, '{"type":"timer","minSeconds":300}'::jsonb, 10, '{"kind":"ramp_stage","atLeast":"initiate"}'::jsonb, 4) on conflict (game_id, key) do nothing;
insert into public.quests (game_id, key, pillar, title, description, why, founding, schedule, "window", proof, xp, unlock, sort_order) values ((select id from public.games where slug = 'g1'), 'g1.money', 'financial', 'Money minute', 'Twice a week, update the four numbers that tell the truth about your money: what came in, what you are worth, what you could touch today, and what your life costs per month.', 'What you measure becomes visible. What becomes visible can be managed.', false, '{"kind":"weekly_quota","perWeek":2}'::jsonb, '{"kind":"anytime"}'::jsonb, '{"type":"metrics","fields":[{"key":"weeklyIncome","label":"Total weekly income","prefix":"$","hint":"Everything that came in this week — paychecks, side gigs, anything."},{"key":"netWorth","label":"Net worth","prefix":"$","hint":"Everything you own minus everything you owe."},{"key":"cashOnHand","label":"Cash on hand","prefix":"$","hint":"How much cash could I access today?"},{"key":"monthlyBurn","label":"Monthly burn","prefix":"$","hint":"How much does it cost me to maintain my current life for one month?"}]}'::jsonb, 10, '{"kind":"ramp_stage","atLeast":"initiate"}'::jsonb, 5) on conflict (game_id, key) do nothing;
insert into public.quests (game_id, key, pillar, title, description, why, founding, schedule, "window", proof, xp, unlock, sort_order) values ((select id from public.games where slug = 'g1'), 'g1.connect', 'social', 'One intentional connection', 'One deliberate act of connection — a call, a message, a meet-up, an act of kindness, or a boundary held.', 'No one carves alone. Relationships are the load-bearing walls of a good life, and they only hold if you show up on purpose.', false, '{"kind":"weekly_quota","perWeek":3}'::jsonb, '{"kind":"anytime"}'::jsonb, '{"type":"text","minChars":3,"maxChars":200}'::jsonb, 15, '{"kind":"ramp_stage","atLeast":"initiate"}'::jsonb, 6) on conflict (game_id, key) do nothing;
insert into public.quests (game_id, key, pillar, title, description, why, founding, schedule, "window", proof, xp, unlock, sort_order) values ((select id from public.games where slug = 'g1'), 'g1.reset', 'environmental', '10-minute space reset (physical or digital)', 'Ten minutes decluttering a space — a room, a desk, an inbox, your phone. Before/after photo optional.', 'Your space is your mind''s outer layer. Ten minutes of clearing resets both — and a clean slate compounds.', false, '{"kind":"weekly_quota","perWeek":3}'::jsonb, '{"kind":"anytime"}'::jsonb, '{"type":"photo_optional"}'::jsonb, 10, '{"kind":"ramp_stage","atLeast":"initiate"}'::jsonb, 7) on conflict (game_id, key) do nothing;
insert into public.quests (game_id, key, pillar, title, description, why, founding, schedule, "window", proof, xp, unlock, sort_order) values ((select id from public.games where slug = 'g1'), 'g1.play', 'recreational', '30 minutes of play', 'Thirty minutes of genuine play — a hobby, a game for fun, sport, time outdoors, or a screen-free break.', 'Rest is part of the protocol, not a cheat code. A grind with no play is just erosion — play is what makes the rest sustainable.', false, '{"kind":"weekly_quota","perWeek":3}'::jsonb, '{"kind":"anytime"}'::jsonb, '{"type":"duration","minMinutes":30}'::jsonb, 10, '{"kind":"ramp_stage","atLeast":"initiate"}'::jsonb, 8) on conflict (game_id, key) do nothing;
